import pytest

from bedrock_protocol import v1001, v2168

VERSIONS = {"v1001": v1001, "v2168": v2168}

# generated by gophertunnel b8bd735:
# &packet.TrimData{Patterns: []protocol.TrimPattern{{ItemName: "item_a", PatternID: "pat_a"}},
# Materials: []protocol.TrimMaterial{{MaterialID: "mat_a", Colour: "c", ItemName: "item_b"}}}
GOLDEN = bytes.fromhex("01066974656d5f61057061745f6101056d61745f610163066974656d5f62")

# generated by gophertunnel b8bd735:
# &packet.TrimData{}
EMPTY = bytes.fromhex("0000")

GOLDENS = [
    pytest.param(
        version.TrimDataPacket(
            trim_patterns=[version.TrimPattern(item_name="item_a", pattern_id="pat_a")],
            trim_materials=[version.TrimMaterial(material_id="mat_a", color="c", item_name="item_b")],
        ),
        GOLDEN,
        id=f"{name}-one-pattern-one-material",
    )
    for name, version in VERSIONS.items()
] + [
    pytest.param(
        version.TrimDataPacket(trim_patterns=[], trim_materials=[]),
        EMPTY,
        id=f"{name}-empty",
    )
    for name, version in VERSIONS.items()
]


@pytest.mark.parametrize("version", VERSIONS.values(), ids=VERSIONS.keys())
def test_trim_data_is_packet_302(version):
    assert version.PACKETS[302] is version.TrimDataPacket


@pytest.mark.parametrize(("packet", "golden"), GOLDENS)
def test_trim_data_encodes_to_its_golden(packet, golden):
    assert bytes(packet) == golden


@pytest.mark.parametrize(("packet", "golden"), GOLDENS)
def test_trim_data_decodes_from_its_golden(packet, golden):
    assert type(packet).from_bytes(golden) == packet


def test_trim_data_is_one_type_across_the_two_eras():
    assert v1001.TrimDataPacket is v2168.TrimDataPacket
